/** Lo que va encima de la cabeza y tapa la flor del frailejón. */
export const TAPAN_FLOR = new Set([
  'gorro', 'gorra', 'fiesta', 'vaquero', 'vueltiao', 'mago', 'corona', 'chef',
  'obra', 'boina', 'copa', 'navidad', 'gato', 'conejo', 'pirata', 'antenas',
  'vikingo', 'paja', 'dormir', 'safari', 'helice', 'bombero', 'reno', 'bruja',
  'pescador', 'moto', 'bici', 'aviadorgorro', 'lazo', 'marinero', 'capitan', 'tricornio',
  'mariachi', 'rana', 'oso', 'astronauta', 'cono', 'chullo', 'aguadeno', 'bufon',
  'romano', 'diablito', 'nube', 'ducha', 'reves', 'minero', 'detective', 'fedora',
  'playa', 'elfo', 'raton', 'zorro', 'panda', 'huevo', 'estrellas', 'pollito',
]);

// ---- 500 variantes de color (sumi-variantes.ts) ----
for (const [dibujos, lista] of [
  [DIBUJOS_CABEZA, VARIANTES.cabeza], [DIBUJOS_CARA, VARIANTES.cara], [DIBUJOS_MANO, VARIANTES.mano], [DIBUJOS_FONDO, VARIANTES.fondo],
] as const) {
  for (const v of lista) dibujos[v.id] = v.dibujo;
}
for (const v of VARIANTES.espalda) DIBUJOS_ESPALDA[v.id] = { atras: v.dibujo, frente: '' };
for (const v of VARIANTES.cabeza) {
  if (!VARIANTES_NO_TAPAN_FLOR.some(base => v.id.startsWith(base + '-'))) TAPAN_FLOR.add(v.id);
}
